:"feder-aragon-2021-2027-20261001.json","source_updated":"2026-10-01","beneficiary_identity_consistent":false,"reported_nif":"B72842990","source_warning":"El beneficiario y el nombre de la operación no coinciden en la fuente. No se utiliza el NIF de esta fila ni se vincula la actuación por el campo de beneficiario."}],"related_company_operations":[{"operation_code":"D2021092","year":2021,"line":"IDIS-REACT","beneficiary":"CENTRO TECNOLOGICO AGROPECUARIO CINCO VILLAS, SL","feder_beneficiary_id":"ES51M888","operation_name":"CENTRO TECNOLOGICO AGROPECUARIO CINCO VILLAS, S.L.","description":"Adquisición e instalación de un equipo ICP-AES para el análisis y control de metales y metales pesados en diferentes tipos de muestras como agua, fertilizantes y cultivos, ha hecho necesaria la ampliación de las nuestras instalaciones para ofertar este servicio. Dentro de nuestro compromiso de desarrollo sostenible y desde el punto de vista medioambiental, con estas nuevas instalaciones de gases, eléctricas y ampliación de locales se consiguen reducir las emisionhes ya que el nuevo equipo no consume combustibles fósiles y no necesita agua para su refrigeración. Este equipo vienen a sustituir al que se utilizaba anteriormente y que consumia para su funcionamiento gas acetileno. En orden a la transformación digital de nuestros procesos para la gestión de todos los datos generados por este equipo y en general para toda la actividad de la empresa, se han adquirido nuevbos equipos informáticos y un software integral que gestiona todo el proceso desde la recepción de una muestra para analizar hasta el envío del resultado mediante un informe, evitando así pérdidas de información y el uso de varias aplicaciones informaticas. Así se pretende unificar en un solo programa toda la información prar poder trabajar en red convirtiendose este software en una herramienta de recursos compartidos que facilita el acceso a los datos desde cualquier lugar o a través de cualquier dispositivo. Siguiendo con nuestra estrategia de crecimiento y diferenciación competitiva hemos actualizado nuestra página web con una zona de acceso a los clientes en la que pueden consultar sus informes de analíticas y acceder a archivos pdf categorizados por tipos de muestra. Gracias a la asesoría para la implantación de la ISO 17025 se mejora determinados procesos de trbajo reduciendo así costes, recursos y tiempo.","start_date":"01/02/2020","end_date":"31/07/2021","feder_operation_cost":6142.0,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Ejea de los Caballeros","municipality_code":"50095","intervention":"004 Inversión productiva relativas a la cooperación entre grandes empresas y PYME para desarrollar productos y servicios en tecnologías de la información y las comunicaciones (TIC), comercio electrónico y mayor demanda de TIC.","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=516","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":516,"source_updated":"2025-05-29"},{"operation_code":"D2022031","year":2022,"line":"IDIS-REACT","beneficiary":"CENTRO TECNOLOGICO AGROPECUARIO CINCO VILLAS, SL","feder_beneficiary_id":"ES51M888","operation_name":"CENTRO TECNOLOGICO AGROPECUARIO CINCO VILLAS, S.L.","description":"Implementar nuevas tecnologías analíticas para mejorar sus procesos de digitalización que aúne todos los procesos de trabajo, procedimientos en laboratorio, informes técnicos, coste y gestión para mejorar la productividad y la eficiencia de todos los procesos realizados en la empresa.","start_date":"01/02/2021","end_date":"31/08/2022","feder_operation_cost":160.0,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Ejea de los Caballeros","municipality_code":"50095","intervention":"004 Inversión productiva relativas a la cooperación entre grandes empresas y PYME para desarrollar productos y servicios en tecnologías de la información y las comunicaciones (TIC), comercio electrónico y mayor demanda de TIC.","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=567","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":567,"source_updated":"2025-05-29"},{"operation_code":"V2021049","year":2021,"line":"IDIS-REACT","beneficiary":"CENTRO TECNOLOGICO AGROPECUARIO CINCO VILLAS, SL","feder_beneficiary_id":"ES51M888","operation_name":"CENTRO TECNOLOGICO AGROPECUARIO CINCO VILLAS, S.L.","description":"Adquisición e instalación de un equipo ICP-AES para el análisis y control de metales y metales pesados en diferentes tipos de muestras como agua, fertilizantes y cultivos, ha hecho necesaria la ampliación de las nuestras instalaciones para ofertar este servicio. Dentro de nuestro compromiso de desarrollo sostenible y desde el punto de vista medioambiental, con estas nuevas instalaciones de gases, eléctricas y ampliación de locales se consiguen reducir las emisionhes ya que el nuevo equipo no consume combustibles fósiles y no necesita agua para su refrigeración. Este equipo vienen a sustituir al que se utilizaba anteriormente y que consumia para su funcionamiento gas acetileno. En orden a la transformación digital de nuestros procesos para la gestión de todos los datos generados por este equipo y en general para toda la actividad de la empresa, se han adquirido nuevbos equipos informáticos y un software integral que gestiona todo el proceso desde la recepción de una muestra para analizar hasta el envío del resultado mediante un informe, evitando así pérdidas de información y el uso de varias aplicaciones informaticas. Así se pretende unificar en un solo programa toda la información prar poder trabajar en red convirtiendose este software en una herramienta de recursos compartidos que facilita el acceso a los datos desde cualquier lugar o a través de cualquier dispositivo. Siguiendo con nuestra estrategia de crecimiento y diferenciación competitiva hemos actualizado nuestra página web con una zona de acceso a los clientes en la que pueden consultar sus informes de analíticas y acceder a archivos pdf categorizados por tipos de muestra. Gracias a la asesoría para la implantación de la ISO 17025 se mejora determinados procesos de trbajo reduciendo así costes, recursos y tiempo.","start_date":"01/02/2020","end_date":"31/07/2021","feder_operation_cost":30365.0,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Ejea de los Caballeros","municipality_code":"50095","intervention":"071 Desarrollo y promoción de empresas especializadas en prestación de servicios que contribuyen a la economía con bajas emisiones de carbono y a la resistencia al cambio climático (incluyendo el apoyo a dichos servicios)","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=1116","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":1116,"source_updated":"2025-05-29"},{"operation_code":"V2022023","year":2022,"line":"IDIS-REACT","beneficiary":"CENTRO TECNOLOGICO AGROPECUARIO CINCO VILLAS, SL","feder_beneficiary_id":"ES51M888","operation_name":"CENTRO TECNOLOGICO AGROPECUARIO CINCO VILLAS, S.L.","description":"Implementar nuevas tecnologías analíticas para mejorar sus procesos de digitalización que aúne todos los procesos de trabajo, procedimientos en laboratorio, informes técnicos, coste y gestión para mejorar la productividad y la eficiencia de todos los procesos realizados en la empresa.","start_date":"01/02/2021","end_date":"31/08/2022","feder_operation_cost":23821.0,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Ejea de los Caballeros","municipality_code":"50095","intervention":"071 Desarrollo y promoción de empresas especializadas en prestación de servicios que contribuyen a la economía con bajas emisiones de carbono y a la resistencia al cambio climático (incluyendo el apoyo a dichos servicios)","source_url":"https://www.dgfc.sepg.hacienda.gob.